insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'lote_9_v1'
from (values
('114.53.c.1.A',3,'At a job site where the target language is used, which is professional etiquette on a phone call?','["state who you are and why you are calling", "skip the greeting and demand help", "speak only slang", "hang up without a word"]'::jsonb,0,'Introductions and clear purpose are standard etiquette.','original'),
('114.53.c.1.A',3,'Introducing a colleague to a client is an example of:','["a private diary", "professional protocol", "a casual joke", "a spelling test"]'::jsonb,1,'Protocol covers introductions and correct address.','original'),
('114.53.c.1.B',3,'An informal written exchange at work, such as a short message to a teammate, should still be:','["left blank", "full of unexplained code", "clear and appropriate for the setting", "rude on purpose"]'::jsonb,2,'Informal does not mean careless.','original'),
('114.53.c.1.B',3,'Which conversation topic fits a workplace chat about a project?','["a private family quarrel", "an insult to a customer", "gossip about a rival", "the schedule for the next delivery"]'::jsonb,3,'Workplace talk stays on professional topics.','original'),
('114.53.c.1.C',4,'Communicating with diverse individuals works best when you:','["adapt your style to the listener", "ignore questions", "speak only louder", "use the same words every time"]'::jsonb,0,'Strategies include adjusting vocabulary and pace.','original'),
('114.53.c.1.C',4,'Which is a strategy for talking with a client who is still learning the language?','["never repeating anything", "speaking clearly and checking understanding", "using as much slang as possible", "talking very fast"]'::jsonb,1,'Clarity and checking help communication.','original'),
('114.53.c.1.D',4,'Evaluating how effective your communication was means asking:','["how many words you used", "whether you were loud", "whether the other person understood and acted on it", "how long you talked"]'::jsonb,2,'Effectiveness is measured by results.','original'),
('114.53.c.1.D',4,'After a meeting, reflecting on what was unclear is useful for:','["erasing notes", "avoiding future meetings", "blaming others", "improving future communication"]'::jsonb,3,'Evaluation drives improvement.','original'),
('114.53.c.1.E',4,'Giving complex oral instructions for a task requires:','["clear, ordered steps", "a single vague word", "silence", "random order"]'::jsonb,0,'Sequencing makes instructions easy to follow.','original'),
('114.53.c.1.E',4,'A good way to confirm you understood an instruction is to:','["walk away", "repeat it back in your own words", "change the task", "nod and guess"]'::jsonb,1,'Restating checks understanding.','original'),
('114.53.c.1.F',4,'Register in speech refers to:','["the pitch of a phone", "the cash drawer", "how formal or informal the language is", "how loud the room is"]'::jsonb,2,'Register is the level of formality.','original'),
('114.53.c.1.F',4,'Which choice shows a culturally appropriate greeting to a new client in many professional settings?','["an unrelated song", "ignoring them", "a joke at their expense", "a polite, formal greeting"]'::jsonb,3,'Formal greetings show respect.','original'),
('114.53.c.1.G',4,'Writing a business email to a client calls for:','["an appropriate tone and style", "no greeting or closing", "texting abbreviations only", "all capital letters"]'::jsonb,0,'Written register should match the audience.','original'),
('114.53.c.1.G',4,'A culturally appropriate closing in a professional letter is:','["an emoji only", "a courteous sign-off", "an insult", "nothing at all"]'::jsonb,1,'Closings follow cultural conventions.','original'),
('114.53.c.2.A',3,'Listening comprehension skills at work help you to:','["avoid people", "talk over others", "build good relationships with clients and coworkers", "interrupt more often"]'::jsonb,2,'Active listening strengthens relationships.','original'),
('114.53.c.2.A',3,'Which nonverbal behavior shows attentiveness?','["looking at the floor the whole time", "rolling your eyes", "turning away", "making appropriate eye contact"]'::jsonb,3,'Nonverbal cues signal respect.','original'),
('114.53.c.2.B',4,'Paraphrasing the main idea of a business report means:','["restating its central point in fewer, original words", "adding new facts", "copying the whole report", "hiding the topic"]'::jsonb,0,'A paraphrase keeps the meaning.','original'),
('114.53.c.2.B',4,'In an industry article, supporting details are the:','["page numbers", "facts and examples that back the main idea", "advertisements", "article''s title only"]'::jsonb,1,'Details support the main idea.','original'),
('114.53.c.2.C',4,'Comparing business practices in two countries is a way to:','["learn a recipe", "draw a map", "understand cultural differences at work", "play a sport"]'::jsonb,2,'Practices and perspectives vary across cultures.','original'),
('114.53.c.2.C',4,'Which could differ between workplace cultures?','["the speed of light", "the color of the sky", "the number of hours in a day", "how directly feedback is given"]'::jsonb,3,'Communication norms vary culturally.','original'),
('114.53.c.2.D',3,'Using prior knowledge when reading a work document means:','["connecting new information to what you already know", "guessing blindly", "skipping the title", "ignoring the document"]'::jsonb,0,'Background knowledge aids interpretation.','original'),
('114.53.c.2.D',3,'If a spoken instruction is unclear, prior experience can help you:','["refuse to listen", "interpret the likely meaning", "leave immediately", "change the subject"]'::jsonb,1,'Experience supports inference.','original'),
('114.53.c.2.E',4,'Applying data to evaluate performance might involve:','["ignoring the numbers", "inventing numbers", "comparing results to a goal", "hiding the results"]'::jsonb,2,'Data should be tied to a standard.','original'),
('114.53.c.2.E',4,'If sales data show a steady drop, a good next step is to:','["delete the report", "pretend nothing changed", "blame a coworker", "use the data to propose a solution"]'::jsonb,3,'Data supports problem solving.','original'),
('114.53.c.2.F',3,'Following a workplace procedure correctly means:','["doing each step as directed", "skipping steps to save time", "changing steps at random", "ignoring safety rules"]'::jsonb,0,'Procedures protect quality and safety.','original'),
('114.53.c.2.F',3,'A written directive from a supervisor should be:','["ignored", "understood and followed, with questions asked if unclear", "hidden", "copied wrongly"]'::jsonb,1,'Clarify before acting if unsure.','original'),
('114.53.c.3.A',3,'Applying spoken and written conventions means:','["skipping punctuation", "ignoring grammar", "using correct grammar, spelling and punctuation", "using random spelling"]'::jsonb,2,'Conventions make writing professional.','original'),
('114.53.c.3.A',3,'Which sentence follows written conventions?','["meeting nine begins", "the meeting begins at nine oclock", "begins meeting at the", "The meeting begins at nine o''clock."]'::jsonb,3,'Capitalization, apostrophes and word order are correct.','original'),
('114.53.c.3.B',4,'Presenting analyzed data effectively might use:','["a chart or table with a clear summary", "an unlabeled blur", "a blank page", "a rumor"]'::jsonb,0,'Formats should make data easy to read.','original'),
('114.53.c.3.B',4,'The best way to communicate findings to a client is to:','["use the hardest format", "use a format suited to the audience", "speak in riddles", "skip the findings"]'::jsonb,1,'Know your audience.','original'),
('114.53.c.3.C',4,'Designing a professional product, such as a brochure, requires:','["no text", "no plan", "a clear purpose and an appropriate style", "random colors only"]'::jsonb,2,'Design follows purpose and audience.','original'),
('114.53.c.3.C',4,'Before presenting a product to a client, you should:','["send it unchecked", "remove all details", "hide the title", "check it for accuracy and polish"]'::jsonb,3,'Quality control matters.','original'),
('114.53.c.3.D',4,'Creating a visual presentation for an industry audience means:','["organizing information clearly with supporting images", "using no visuals", "reading from a blank screen", "cramming every word onto one slide"]'::jsonb,0,'Visuals support the message.','original'),
('114.53.c.3.D',4,'An effective oral presentation includes:','["random order", "a clear opening, body and conclusion", "only a conclusion", "no structure"]'::jsonb,1,'Structure helps listeners follow.','original'),
('114.53.c.4.A',3,'Strategies to infer an unfamiliar industry word include:','["skipping the sentence", "changing the topic", "using context clues and word parts", "guessing wildly"]'::jsonb,2,'Context and roots help.','original'),
('114.53.c.4.A',3,'If you meet an unknown technical term, you can first:','["erase it", "laugh at it", "stop reading", "look at the sentence around it"]'::jsonb,3,'Surrounding words give hints.','original'),
('114.53.c.4.B',3,'Applying new academic vocabulary means:','["using the words correctly in your own work", "spelling them wrong", "memorizing without using", "avoiding the words"]'::jsonb,0,'Use makes vocabulary stick.','original'),
('114.53.c.4.B',3,'A good way to learn industry vocabulary is to:','["avoid reading", "use new terms in sentences and conversations", "guess meanings forever", "never ask questions"]'::jsonb,1,'Active use builds retention.','original'),
('114.53.c.4.C',4,'Dialects used in a community mean that the same language can:','["be only written", "never change", "differ in words, sounds or expressions", "have a single accent"]'::jsonb,2,'Dialects are regional or social varieties.','original'),
('114.53.c.4.C',4,'Understanding local dialects at work helps a professional to:','["avoid conversation", "skip training", "confuse clients", "serve the community more effectively"]'::jsonb,3,'Dialect awareness aids service.','original'),
('114.53.c.4.D',4,'Technical jargon is:','["specialized vocabulary used within a field", "everyday slang only", "a spelling mistake", "a type of music"]'::jsonb,0,'Jargon is the language of a profession.','original'),
('114.53.c.4.D',4,'Abbreviations in a profession are used to:','["avoid communication", "save time among people who know them", "replace all words", "confuse customers"]'::jsonb,1,'Abbreviations are shorthand for insiders.','original'),
('114.53.c.5.A',3,'Communicating with employers in the target language should be:','["rude and careless", "silent", "respectful and appropriate to the workplace", "off topic"]'::jsonb,2,'Appropriate communication fits employers, clients and coworkers.','original'),
('114.53.c.5.A',3,'Speaking to a client and speaking to a close friend usually differ in:','["the time of day", "the size of the building", "the number of words in the dictionary", "level of formality"]'::jsonb,3,'Audience shapes register.','original'),
('114.53.c.5.B',3,'Professional etiquette includes being:','["punctual and courteous", "distracted and loud", "silent and absent", "late and rude"]'::jsonb,0,'Etiquette shows respect.','original'),
('114.53.c.5.B',3,'Which shows good etiquette in a meeting?','["checking a game on your phone", "not interrupting while others speak", "talking over colleagues", "arriving an hour late"]'::jsonb,1,'Courtesy supports teamwork.','original'),
('114.53.c.5.C',4,'Confidentiality means:','["sharing records with strangers", "posting client data online", "keeping private information private", "telling coworkers everything"]'::jsonb,2,'Confidentiality protects clients.','original'),
('114.53.c.5.C',4,'A fiduciary duty is an obligation to:','["avoid all paperwork", "maximize your own profit only", "ignore a client", "act in the best interest of another party"]'::jsonb,3,'Fiduciary duty is a legal and ethical obligation.','original'),
('114.53.c.5.D',3,'A mock interview in the target language helps you to:','["practice career conversations", "skip preparation", "avoid job seeking", "hide your skills"]'::jsonb,0,'Practice builds confidence.','original'),
('114.53.c.5.D',3,'In a job interview, a strong answer is:','["vague and off topic", "clear, honest and relevant to the question", "a single word", "rude"]'::jsonb,1,'Good answers address the question.','original'),
('114.53.c.5.E',3,'Setting goals for target-language use at work means:','["giving up early", "having no plan", "deciding what you want to achieve and tracking it", "ignoring progress"]'::jsonb,2,'Goals guide growth.','original'),
('114.53.c.5.E',3,'Reflecting on your progress helps you to:','["avoid learning", "stop practicing", "hide mistakes", "see strengths and next steps"]'::jsonb,3,'Reflection informs improvement.','original'),
('114.53.c.5.F',3,'Following copyright law means:','["not copying others'' work without permission", "claiming others'' work", "copying anything online", "ignoring credits"]'::jsonb,0,'Copyright protects creators.','original'),
('114.53.c.5.F',3,'Using technology ethically at work includes:','["ignoring policies", "respecting privacy and following rules", "hacking systems", "sharing passwords"]'::jsonb,1,'Ethical technology use follows rules and respects others.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Languages Other Than English' and d.language = 'en'
on conflict (fingerprint) do nothing;
